INSERT INTO `maira_data` (`primkey`, `record_id`, `platform`, `run_at`, `time_of_day`, `days_of_week`, `payload`, `status`, `last_run_date`, `reg_date`, `hive_site_id`, `hive_site_name`, `repeat_type`, `task_name`) VALUES
(1, 'YF4GH9Y', 'Octane-local', '2026-10-01 15:22:00', '21:26', 'Wed,Thu,Fri', '{\n  "persona": "SALES MONITOR TODAY",\n  "audience": "admin",\n  "weight": 5,\n\n  "fetch": {\n    "Sales": {\n      "table": "fuel_sales",\n      "where": "sale_date = today",\n      "columns": ["total_amount"],\n      "lookup": ["fuel_type"],\n      "group_by": "fuel_type",\n      "compare_with": "sale_date = yesterday"\n    },\n    "Sent": {\n      "table": "sales_kra_logs",\n      "where": "status = ''sent'' AND created_at = today"\n    },\n    "Failed": {\n      "table": "sales_kra_logs",\n      "where": "status = ''failed'' AND created_at = today"\n    },\n    "Stock": {\n      "table": "tank_level_history",\n      "where": "movement_time = today",\n      "columns": ["liters_out"]\n    },\n    "Flags": {\n      "table": "sales_kra_logs",\n      "where": "status = ''open''"\n    },\n    "Shift": {\n      "table": "shifts",\n      "where": "status = ''open''",\n      "lookup": ["opened_by"],\n      "if_empty": "No shift open"\n    }\n  }, \n\n  "lines": {\n    "KRA": {\n      "rules": [\n        { "if": "Failed.count is not 0", "say": "{Sent.count} receipts sent to KRA, {Failed.count} waiting. The system retries at 8 PM." },\n        { "if": "Sent.count is 0",       "say": "No receipts have reached KRA yet today " }\n      ],\n      "if_none": "All {Sent.count} receipts sent to KRA "\n    },\n    "Trend": {\n      "rules": [\n        { "if": "Sales.before.count is 0",                  "say": "No sales yesterday to compare with" },\n        { "if": "Sales.before.change.amount.trend is up",   "say": "Up {Sales.before.change.amount.percent}% on yesterday" },\n        { "if": "Sales.before.change.amount.trend is down", "say": "Down {Sales.before.change.amount.percent}% on yesterday" }\n      ],\n      "if_none": "Same as yesterday"\n    }\n  },\n\n  "message": "Today the system:\\n • Recorded {Sales.count} sales worth {Sales.amount.total|money}\\n • {KRA}\\n • Updated stock on {Stock.qty.total} items\\n • Spotted {Flags.count} things for you\\n\\nTop seller: {Sales.top.item}\\n{Trend}\\n\\nYou did none of it manually.\\nOpen the app to see the details.",\n\n  "skip_if": "Sales.count is 0",\n\n  "fallback_message": "Quiet day so far. No sales recorded yet.\\nThe system is watching and will report as soon as there are.",\n\n  "formats": {\n    "money": "KES #,###"\n  }\n}', 'active', '2026-10-01 21:47:13', '0000-00-00 00:00:00', 'LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm', 'Superadmin', 'once', 'Sales Manager'),
(2, '7BM32TB', 'Octane-local', '2026-10-01 15:22:00', '21:26', 'Wed,Thu,Fri', '{\n  "persona": "SALES MONITOR MONTHLY",\n  "audience": "admin",\n  "weight": 5,\n\n  "fetch": {\n    "Sales": {\n      "table": "fuel_sales",\n      "where": "sale_date >= 2026-06-01 AND sale_date <= 2026-10-01",\n      "columns": ["total_amount"],\n      "lookup": ["fuel_type"],\n      "group_by": "fuel_type",\n      "rank_by": "total_amount",\n      "date_column": "sale_date",\n      "compare_with": "sale_date >= 2026-02-01 AND sale_date < 2026-06-01"\n    },\n    "Sent": {\n      "table": "sales_kra_logs",\n      "where": "status = ''sent'' AND created_at >= 2026-06-01 AND created_at <= 2026-10-01"\n    },\n    "Failed": {\n      "table": "sales_kra_logs",\n      "where": "status = ''failed'' AND created_at >= 2026-06-01 AND created_at <= 2026-10-01"\n    },\n    "Stock": {\n      "table": "tank_level_history",\n      "where": "movement_time >= 2026-06-01 AND movement_time <= 2026-10-01",\n      "columns": ["liters_out"]\n    }\n  },\n\n  "lines": {\n    "KRA": {\n      "rules": [\n        { "if": "Sent.count is 0",       "say": "No receipts have reached KRA in this period ??" },\n        { "if": "Failed.count is not 0", "say": "{Sent.count} receipts sent to KRA, {Failed.count} still waiting" }\n      ],\n      "if_none": "All {Sent.count} receipts sent to KRA ?"\n    },\n    "Trend": {\n      "rules": [\n        { "if": "Sales.before.count is 0",                        "say": "No earlier sales to compare with" },\n        { "if": "Sales.before.change.total_amount.trend is up",   "say": "Up {Sales.before.change.total_amount.percent}% on the 4 months before" },\n        { "if": "Sales.before.change.total_amount.trend is down", "say": "Down {Sales.before.change.total_amount.percent}% on the 4 months before" }\n      ],\n      "if_none": "Same as the 4 months before"\n    }\n  },\n\n  "message": "Since June the system:\\n • Recorded {Sales.count} sales worth {Sales.total_amount.total|money}\\n • {KRA}\\n • Tracked {Stock.liters_out.total|litres} dispensed from your tanks\\n\\nTop seller: {Sales.top.fuel_type}\\n{Trend}\\n\\nYou did none of it manually.\\nOpen the app to see the details.",\n\n  "skip_if": "Sales.count is 0",\n\n  "fallback_message": "No sales recorded in this period.",\n\n  "formats": {\n    "money": "KES #,###",\n    "litres": "#,### L"\n  }\n}', 'active', '2026-10-01 21:47:58', '0000-00-00 00:00:00', 'LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm', 'Superadmin', 'once', 'Sales Manager '),
(3, 'W2M1T8E', 'Octane-local', '2026-10-01 15:22:00', '21:26', 'Wed,Thu,Fri', '{\n  "persona": "SHIFT MONITOR",\n  "audience": "admin",\n  "weight": 9,\n\n  "fetch": {\n    "Shift": {\n      "table": "shifts",\n      "where": "primkey = {shift_id}",\n      "lookup": ["shift_name", "branch_name", "opened_at", "closed_at"]\n    },\n    "Sales": {\n      "table": "fuel_sales",\n      "where": "shift_id = {shift_id}",\n      "columns": ["total_amount", "liters"],\n      "group_by": "fuel_type",\n      "rank_by": "total_amount"\n    },\n    "Credit": {\n      "table": "fuel_sales",\n      "where": "shift_id = {shift_id} AND payment_method = ''credit''",\n      "columns": ["total_amount"]\n    }\n  },\n\n  "lines": {\n    "Products": {\n      "each": "Sales.groups",\n      "say": "{item.fuel_type}\\nVol : {item.liters.total|litres}\\nTotals : {item.total_amount.total|money}",\n      "separator": "\\n\\n",\n      "if_none": "No sales recorded"\n    }\n  },\n\n  "message": "Shift Name : {Shift.first.shift_name}\\nBranch : {Shift.first.branch_name}\\nOpen Time : {Shift.first.opened_at|stamp}\\nClose Time : {Shift.first.closed_at|stamp}\\n\\nTotal Sales : {Sales.total_amount.total|money}\\nTotal Volume Sold : {Sales.liters.total|litres}\\nTotal Credit : {Credit.total_amount.total|money}\\n\\nSales per Product :\\n{Products}\\n\\nReport Date : {Shift.first.closed_at|stamp}",\n\n  "formats": {\n    "money": "KES #,###.00",\n    "litres": "#,###.00 L",\n    "stamp": "YYYY-MM-DD hh:mm:ss A"\n  }\n}', 'active', '2026-10-01 21:47:58', '0000-00-00 00:00:00', 'LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm', 'Superadmin', 'once', 'Sales Manager '),
(4, 'XCHBW1L', 'Octane-local', '2026-10-01 15:22:00', '09:06', 'Wed,Thu,Fri,Sat', '{\n  "persona": "{Shift.first.location_id} SHIFT MONITOR",\n  "audience": "admin",\n  "weight": 9,\n  "paths" : true,\n  "subject":"{Shift.first.location_id} closing shift report for {Salesdata.latest.sale_date|stamp}",\n  "fetch": {\n    "Shift": {\n      "table": "shifts",\n      "where": "status=''closed'' and open_time in last 100 days ",\n      "lookup": ["shift_name", "location_id", "open_time", "close_time"],\n      "join" : {"location_id":"business_branches.branch_name|record_id"}\n    },\n    \n    "Sales": {\n      "table": "fuel_sales",\n      "where" : "sale_date in last 100 days ",\n      "columns": ["total_amount", "quantity_sold_litres"],\n      "group_by": "fuel_type",\n      "rank_by": "total_amount"\n    },\n    \n    "Salesdata": {\n      "table": "fuel_sales",\n      "where" : "sale_date in last 100 days ",\n      "lookup" : ["sale_date"],\n      "order_by": "primkey",\n      "order_type" : "DESC"\n    },    \n    \n    "Attendants":{\n      "table":"fuel_sales",\n      "where" : "sale_date in last 100 days ",\n      "columns" : ["total_amount","quantity_sold_litres"],\n      "group_by" : "sold_by_staff_id",\n      "rank_by" : "total_amount",\n      "join":{"sold_by_staff_id":"system_users.name|record_id"}\n    },\n    \n    "Credit": {\n      "table": "fuel_sales",\n      "where": "sale_method= ''credit''",\n      "columns": ["total_amount"]\n    }\n  },\n\n  "lines": {\n    "Products": {\n      "each": "Sales.groups",\n      "say": "{item.fuel_type}\\nVol : {item.quantity_sold_litres.total|litres}\\nTotals : {item.total_amount.total|money}",\n      "separator": "\\n\\n",\n      "if_none": "No sales recorded"\n    },\n    "Attendant_analysis": {\n      "each": "Attendants.groups",\n      "say": "{item.sold_by_staff_id}\\nVol : {item.quantity_sold_litres.total|litres}\\nTotals : {item.total_amount.total|money}",\n      "separator": "\\n\\n",\n      "if_none": "No sales recorded"\n    }    \n  },\n\n  "message": "Shift Name : {Shift.first.shift_name}\\nBranch : {Shift.first.location_id}\\nOpen Time : {Shift.first.open_time|stamp}\\nClose Time : {Shift.first.close_time|stamp}\\n\\nTotal Sales : {Sales.total_amount.total|money}\\nTotal Volume Sold : {Sales.quantity_sold_litres.total|litres}\\nTotal Credit : {Credit.total_amount.total|money}\\n\\nSales per Product :\\n{Products}\\n\\nSales Per Attendant:\\n{Attendant_analysis}\\n\\nReport Date : {Shift.first.close_time|stamp}",\n\n  "formats": {\n    "money": "KES #,###.00",\n    "litres": "#,###.00 L",\n    "stamp": "YYYY-MM-DD hh:mm:ss A"\n  }\n}', 'active', '2026-10-02 13:04:23', '0000-00-00 00:00:00', 'LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm', 'Superadmin', 'once', 'Shift monitor - Octane');
