(674, 'rbk_1790873938948_54', 'maira_data', 'UPDATE', 'primkey=''1''', '2026-10-01 19:58:59', '[{"primkey":1,"record_id":"YF4GH9Y","platform":"Octane-local","run_at":"2026-10-01 15:22:00","time_of_day":"20:33","days_of_week":"Wed,Thu,Fri","payload":"{\\n  \\"persona\\": \\"SALES MONITOR\\",\\n  \\"audience\\": \\"admin\\",\\n  \\"weight\\": 5,\\n\\n  \\"fetch\\": {\\n    \\"Sales\\": {\\n      \\"table\\": \\"sales\\",\\n      \\"where\\": \\"date = today\\",\\n      \\"columns\\": [\\"amount\\"],\\n      \\"lookup\\": [\\"item\\"],\\n      \\"group_by\\": \\"item\\",\\n      \\"compare_with\\": \\"date = yesterday\\"\\n    },\\n    \\"Sent\\": {\\n      \\"table\\": \\"etims_log\\",\\n      \\"where\\": \\"status = ''sent'' AND date = today\\"\\n    },\\n    \\"Failed\\": {\\n      \\"table\\": \\"etims_log\\",\\n      \\"where\\": \\"status = ''failed'' AND date = today\\"\\n    },\\n    \\"Stock\\": {\\n      \\"table\\": \\"stock_movements\\",\\n      \\"where\\": \\"type = ''sale'' AND date = today\\",\\n      \\"columns\\": [\\"qty\\"]\\n    },\\n    \\"Flags\\": {\\n      \\"table\\": \\"flags\\",\\n      \\"where\\": \\"status = ''open''\\"\\n    },\\n    \\"Shift\\": {\\n      \\"table\\": \\"shifts\\",\\n      \\"where\\": \\"status = ''open''\\",\\n      \\"lookup\\": [\\"opened_by\\"],\\n      \\"if_empty\\": \\"No shift open\\"\\n    }\\n  },\\n\\n  \\"lines\\": {\\n    \\"KRA\\": {\\n      \\"rules\\": [\\n        { \\"if\\": \\"Failed.count is not 0\\", \\"say\\": \\"{Sent.count} receipts sent to KRA, {Failed.count} waiting. The system retries at 8 PM.\\" }\\n      ],\\n      \\"if_none\\": \\"All {Sent.count} receipts sent to KRA ?\\"\\n    },\\n    \\"Trend\\": {\\n      \\"rules\\": [\\n        { \\"if\\": \\"Sales.before.change.amount.trend is up\\",   \\"say\\": \\"Up {Sales.before.change.amount.percent}% on yesterday\\" },\\n        { \\"if\\": \\"Sales.before.change.amount.trend is down\\", \\"say\\": \\"Down {Sales.before.change.amount.percent}% on yesterday\\" }\\n      ],\\n      \\"if_none\\": \\"Same as yesterday\\"\\n    }\\n  },\\n\\n  \\"message\\": \\"Today the system:\\\\n • Recorded {Sales.count} sales worth {Sales.amount.total|money}\\\\n • {KRA}\\\\n • Updated stock on {Stock.qty.total} items\\\\n • Spotted {Flags.count} things for you\\\\n\\\\nTop seller: {Sales.top.item}\\\\n{Trend}\\\\n\\\\nYou did none of it manually.\\\\nOpen the app to see the details.\\",\\n\\n  \\"skip_if\\": \\"Sales.count is 0\\",\\n\\n  \\"fallback_message\\": \\"Quiet day so far. No sales recorded yet.\\\\nThe system is watching and will report as soon as there are.\\",\\n\\n  \\"formats\\": {\\n    \\"money\\": \\"KES #,###\\"\\n  }\\n}","status":"active","last_run_date":"2026-10-01 15:22:00","reg_date":"0000-00-00 00:00:00","hive_site_id":"LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm","hive_site_name":"Superadmin","repeat_type":"once","task_name":"Sales Manager"}]', 'LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm', 'Superadmin'),
