ucts\\": {\\n      \\"each\\": \\"Sales.groups\\",\\n      \\"say\\": \\"{item.fuel_type}\\\\nVol : {item.quantity_sold_litres.total|litres}\\\\nTotals : {item.total_amount.total|money}\\",\\n      \\"separator\\": \\"\\\\n\\\\n\\",\\n      \\"if_none\\": \\"No sales recorded\\"\\n    },\\n    \\"Attendant_analysis\\": {\\n      \\"each\\": \\"Attendants.groups\\",\\n      \\"say\\": \\"{item.sold_by_staff_id}\\\\nVol : {item.quantity_sold_litres.total|litres}\\\\nTotals : {item.total_amount.total|money}\\",\\n      \\"separator\\": \\"\\\\n\\\\n\\",\\n      \\"if_none\\": \\"No sales recorded\\"\\n    }    \\n  },\\n\\n  \\"message\\": \\"Shift Name : {Shift.first.shift_name}\\\\nBranch : {Shift.first.location_id}\\\\nOpen Time : {Shift.first.open_time|stamp}\\\\nClose Time : {Shift.first.close_time|stamp}\\\\n\\\\nTotal Sales : {Sales.total_amount.total|money}\\\\nTotal Volume Sold : {Sales.quantity_sold_litres.total|litres}\\\\nTotal Credit : {Credit.total_amount.total|money}\\\\n\\\\nSales per Product :\\\\n{Products}\\\\n\\\\nSales Per Attendant:\\\\n{Attendant_analysis}\\\\n\\\\nReport Date : {Shift.first.close_time|stamp}\\",\\n\\n  \\"formats\\": {\\n    \\"money\\": \\"KES #,###.00\\",\\n    \\"litres\\": \\"#,###.00 L\\",\\n    \\"stamp\\": \\"YYYY-MM-DD hh:mm:ss A\\"\\n  }\\n}","status":"active","last_run_date":"2026-10-02 10:29:47","reg_date":"0000-00-00 00:00:00","hive_site_id":"LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm","hive_site_name":"Superadmin","repeat_type":"once","task_name":"Shift monitor"}]', 'LLRR0ZKOXRTCOHN_2024-12-28-07-45-56-pm', 'Superadmin'),
